3	import com.example.rebate.domain.IdempotentRecord;
4	import com.example.rebate.repo.IdempotentRecordRepository;
5	import com.example.rebate.support.FingerprintService;
6	import com.example.rebate.web.ApiException;
7	import com.example.rebate.web.ConflictException;
8	import java.time.OffsetDateTime;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.function.Supplier;
12	import org.springframework.stereotype.Service;
13	
14	/**
15	 * requestId 幂等编排。
16	 *
17	 * <p>占坑与结果回写经 {@link IdempotentTxBoundary} 在独立提交事务中完成，业务动作在
18	 * RebateService 自身事务中执行：业务失败只回滚业务数据，首次结果（含错误码）仍被存档；
19	 * 同键同参永远返回首次结果，同键异参返回 409 且不改变任何批次状态。</p>
20	 */
21	@Service
22	public class IdempotencyService {
23	
24	    private final IdempotentRecordRepository records;
25	    private final IdempotentTxBoundary txBoundary;
26	    private final FingerprintService fingerprints;
27	
28	    public IdempotencyService(IdempotentRecordRepository records,
29	                              IdempotentTxBoundary txBoundary,
30	                              FingerprintService fingerprints) {
31	        this.records = records;
32	        this.txBoundary = txBoundary;
33	        this.fingerprints = fingerprints;
34	    }
35	
36	    /**
37	     * 以幂等方式执行业务动作。
38	     *
39	     * @param opType 操作类型（纳入指纹）
40	     * @param requestId 幂等键
41	     * @param payload 全部业务字段（requestId 已单独纳入指纹；路径变量也算业务字段）
42	     * @param action 首次执行时调用的业务动作（运行于其自身事务）
43	     */
44	    public IdempotentOutcome run(String opType, String requestId, Object payload,
45	                                 Supplier<ServiceResult> action) {
46	        String fp = fingerprints.fingerprint(opType, requestId, payload);
47	        boolean acquired = txBoundary.acquire(requestId, opType, fp);
48	        if (!acquired) {
49	            IdempotentRecord existing = mustFind(requestId);
50	            if (!fp.equals(existing.fingerprint())) {
51	                // 同键异参立即 409，不等待、不触碰任何业务状态。
52	                throw new ConflictException("requestId=" + requestId + " 已用于不同业务参数");
53	            }
54	            // 同键同参并发：等待首次请求完成后回放首次结果。
55	            IdempotentRecord rec = awaitCompletion(requestId);
56	            if (rec == null) {
57	                throw new ConflictException("requestId=" + requestId + " 的首次请求处理超时");
58	            }
59	            return IdempotentOutcome.replay(rec.responseStatus(), rec.responseBody());
60	        }
61	        try {
62	            ServiceResult result = action.get();
63	            txBoundary.complete(requestId, result.status(), fingerprints.toJson(result.body()));
64	            return IdempotentOutcome.first(result.status(), result.body());
65	        } catch (ApiException e) {
66	            // 业务错误同样存档，保证同键重放得到相同错误；业务事务已随异常回滚。
67	            txBoundary.complete(requestId, e.getStatus(),
68	                    fingerprints.toJson(errorBody(e.getStatus(), e.getMessage())));
69	            throw e;
70	        } catch (RuntimeException e) {
71	            // 非预期错误也结束占坑记录，避免同键并发调用永久等待。
72	            txBoundary.complete(requestId, 500, fingerprints.toJson(errorBody(500, "服务内部错误")));
73	            throw e;
74	        }
75	    }
76	
77	    /**
78	     * 同键同参并发：轮询等待首次请求回写结果（有界等待 10 秒）。
79	     */
80	    private IdempotentRecord awaitCompletion(String requestId) {
81	        long deadline = System.currentTimeMillis() + 10_000L;
82	        while (System.currentTimeMillis() < deadline) {
83	            IdempotentRecord rec = mustFind(requestId);
84	            if (rec.responseStatus() != null && rec.responseBody() != null) {
85	                return rec;
86	            }
87	            try {
88	                Thread.sleep(20L);
89	            } catch (InterruptedException e) {
90	                Thread.currentThread().interrupt();
91	                return null;
92	            }
93	        }
94	        return null;
95	    }
96	
97	    private IdempotentRecord mustFind(String requestId) {
98	        List<IdempotentRecord> list = records.find(requestId);
99	        return list.stream().findFirst()
100	                .orElseThrow(() -> new ConflictException("requestId=" + requestId + " 记录不可读"));
101	    }
102	
103	    private Map<String, Object> errorBody(int status, String message) {
104	        return Map.of("timestamp", OffsetDateTime.now().toString(),
105	                "status", status, "error", message);
106	    }
107	}
