1	package com.example.rebate.support;
2	
3	import com.fasterxml.jackson.core.JsonProcessingException;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import java.nio.charset.StandardCharsets;
6	import java.security.MessageDigest;
7	import java.security.NoSuchAlgorithmException;
8	import java.util.HexFormat;
9	import org.springframework.stereotype.Component;
10	
11	/**
12	 * 幂等指纹：SHA-256，覆盖操作类型、requestId 与全部业务字段的规范化 JSON。
13	 */
14	@Component
15	public class FingerprintService {
16	
17	    private final ObjectMapper canonicalMapper;
18	
19	    public FingerprintService(ObjectMapper objectMapper) {
20	        // 复制一份并开启键排序，保证同参数不同字段顺序产生相同指纹。
21	        this.canonicalMapper = objectMapper.copy()
22	                .configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS, true)
23	                .configure(com.fasterxml.jackson.databind.MapperFeature.SORT_PROPERTIES_ALPHABETICALLY, true);
24	    }
25	
26	    /**
27	     * 计算指纹：{@code SHA-256(opType | requestId | 规范化业务字段 JSON)}。
28	     */
29	    public String fingerprint(String opType, String requestId, Object payload) {
30	        String canonical;
31	        try {
32	            canonical = canonicalMapper.writeValueAsString(payload);
33	        } catch (JsonProcessingException e) {
34	            throw new IllegalStateException("幂等指纹序列化失败", e);
35	        }
36	        String raw = opType + '|' + requestId + '|' + canonical;
37	        try {
38	            MessageDigest md = MessageDigest.getInstance("SHA-256");
39	            byte[] digest = md.digest(raw.getBytes(StandardCharsets.UTF_8));
40	            return HexFormat.of().formatHex(digest);
41	        } catch (NoSuchAlgorithmException e) {
42	            throw new IllegalStateException("SHA-256 不可用", e);
43	        }
44	    }
45	
46	    /**
47	     * 将响应序列化为 JSON 文本存储，供同键重放原样返回。
48	     */
49	    public String toJson(Object response) {
50	        try {
51	            return canonicalMapper.writeValueAsString(response);
52	        } catch (JsonProcessingException e) {
