6	/**
7	 * 退税计算规则（纯函数，便于复算与测试）。
8	 *
9	 * <ul>
10	 *   <li>计税依据 = FOB 价 × 退税率（保留 4 位小数，四舍五入）；</li>
11	 *   <li>换汇成本 = 计税依据 ÷ FOB 美元价（保留 6 位小数，四舍五入），合法区间 [5.0, 8.0]，恰在端点合法；</li>
12	 *   <li>到账差异比例 = |到账金额 − 申报税额| ÷ 申报税额（保留 8 位小数），恰 0.5%（0.005）视为一致。</li>
13	 * </ul>
14	 */
15	public final class RebateCalculator {
16	
17	    /** 换汇成本下限（含）。 */
18	    public static final BigDecimal EXCHANGE_COST_MIN = new BigDecimal("5.0");
19	
20	    /** 换汇成本上限（含）。 */
21	    public static final BigDecimal EXCHANGE_COST_MAX = new BigDecimal("8.0");
22	
23	    /** 到账差异容忍比例：恰 0.5% 视为一致。 */
24	    public static final BigDecimal DIFF_TOLERANCE = new BigDecimal("0.005");
