                "/api/batches/" + BATCH + "/clawbacks/" + clawbackId + "/receipts",
                TestFixtures.clawbackReceipt("cb-rc1", "RCV-1", 3000L,
                        "2026-03-01T10:00:00Z", 2), 200);
