import com.example.rebate.testsupport.TestFixtures;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;

/**
 * 新增冲回写操作的 requestId 幂等与结构化指纹：
 * 同键同参重放首次冻结结果、异参 409、失败不占键；业务、版本与幂等结果同事务。
 */
